import sys
import xml.etree.ElementTree as ET
import sqlite3
import json

def parse_xml(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        db_path = None
        query_params = None

        for elem in root:
            if elem.tag == 'database':
                db_path = elem.get('path')
            elif elem.tag == 'query':
                query_params = {
                    'table': elem.get('table'),
                    'column': elem.get('column'),
                    'value': elem.get('value')
                }
        return db_path, query_params
    except Exception as e:
        print(f"ERROR: Failed to parse XML file: {e}", file=sys.stderr)
        sys.exit(1)

def execute_query(db_path, query_params):
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()

        table = query_params['table']
        column = query_params['column']
        value = query_params['value']

        cursor.execute(f"SELECT * FROM {table} WHERE {column} = ?", (value,))
        rows = cursor.fetchall()

        column_names = [desc[0] for desc in cursor.description]

        for row in rows:
            print(json.dumps(dict(zip(column_names, row))))

        conn.close()
    except Exception as e:
        print(f"ERROR: Failed to execute query: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("ERROR: Usage: python query_tool.py <xml_config_file>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    db_path, query_params = parse_xml(xml_path)

    if db_path is None or query_params is None:
        sys.exit(1)

    execute_query(db_path, query_params)

