import sqlite3
import json
import subprocess
import os
import sys

class row_runner:
    cache = {}

    @classmethod
    def load_cache(cls):
        if os.path.exists('row_runner.cache'):
            with open('row_runner.cache', 'r') as f:
                cls.cache = json.load(f)

    @classmethod
    def save_cache(cls):
        with open('row_runner.cache', 'w') as f:
            json.dump(cls.cache, f)

    @classmethod
    def run_command(cls, command):
        if command in cls.cache:
            return cls.cache[command]
        result = subprocess.run(command, shell=True, capture_output=True, text=True)
        cls.cache[command] = result.stdout
        return result.stdout

    @classmethod
    def process_table(cls, db_path, table_name):
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute(f"SELECT id, command FROM {table_name} ORDER BY id ASC")
        rows = cursor.fetchall()
        conn.close()

        output = []
        for row in rows:
            id_, command = row
            output.append({
                'id': id_,
                'output': cls.run_command(command)
            })
        return output

    @classmethod
    def main(cls):
        cls.load_cache()
        db_path = sys.argv[1]
        table_name = sys.argv[2]
        results = cls.process_table(db_path, table_name)
        cls.save_cache()
        print(json.dumps(results))

