from concurrent.futures import ThreadPoolExecutor, as_completed
from xml.etree import ElementTree as ET

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    jobs = []
    for job_elem in root.findall('job'):
        job = {
            'id': job_elem.get('id'),
            'command': job_elem.find('command').text
        }
        jobs.append(job)
    return jobs

def run_job(job_id, command, max_parallel):
    process = subprocess.Popen(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    exit_code = process.wait()
    return exit_code

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('xml_path', help='Path to the XML file containing jobs')
    parser.add_argument('--max-parallel', type=int, default=1, help='Maximum number of parallel jobs')
    args = parser.parse_args()

    jobs = parse_xml(args.xml_path)
    job_results = {}

    with ThreadPoolExecutor(max_workers=args.max_parallel) as executor:
        futures = {executor.submit(run_job, job['id'], job['command'], args.max_parallel): job['id'] for job in jobs}
        for future in as_completed(futures):
            job_id = futures[future]
            try:
                exit_code = future.result()
                job_results[job_id] = exit_code
            except Exception as e:
                job_results[job_id] = -1  # Error code

    print(json.dumps(job_results))

