import os
import sys
import json
import hashlib
import requests

def compute_digest(file_path, manifest_key):
    with open(file_path, 'rb') as f:
        file_bytes = f.read()
    combined = file_bytes + manifest_key.encode('utf-8')
    return hashlib.sha256(combined).hexdigest()

def process_input():
    records = []
    for line in sys.stdin:
        stripped = line.strip()
        if not stripped:
            continue
        path = stripped
        name = os.path.basename(path)
        try:
            size = os.path.getsize(path)
            digest = compute_digest(path, os.getenv('MANIFEST_KEY', ''))
            records.append({
                'name': name,
                'size': size,
                'digest': digest
            })
        except (IOError, OSError):
            continue
    return records

def write_manifest(records):
    with open('manifest.json', 'w', encoding='utf-8') as f:
        json.dump(records, f)

def send_to_endpoint(records):
    try:
        response = requests.post(
            os.getenv('MANIFEST_ENDPOINT'),
            data=json.dumps(records),
            headers={'Content-Type': 'application/json'}
        )
        response.raise_for_status()
        print(response.text)
    except requests.exceptions.RequestException:
        sys.exit(1)

def main():
    records = process_input()
    write_manifest(records)
    send_to_endpoint(records)

if __name__ == '__main__':
    main()

