def parse_rss_item(item):
    title = item.find('title')
    link = item.find('link')
    return title.text if title else None, link.text if link else None

def process_feed(feed_name, feed_url):
    try:
        response = requests.get(feed_url)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'xml')
        first_item = soup.find('item')
        if not first_item:
            return {"name": feed_name, "error": "failed"}

        title, link = parse_rss_item(first_item)
        if title and link:
            return {"name": feed_name, "title": title, "link": link}
        else:
            return {"name": feed_name, "error": "failed"}
    except Exception:
        return {"name": feed_name, "error": "failed"}

