    if len(sys.argv) != 2:
        print(json.dumps({"feeds": []}), end='')
        return

    config_file = sys.argv[1]
    try:
        with open(config_file, 'r') as f:
            config = json.load(f)
    except Exception:
        print(json.dumps({"feeds": [{"name": "failed", "error": "failed"}]}), end='')
        return

    if "feeds" not in config or not isinstance(config["feeds"], list):
        print(json.dumps({"feeds": [{"name": "failed", "error": "failed"}]}), end='')
        return

    results = []
