import sys
import xml.etree.ElementTree as ET
import re

def evaluate_formula(formula, field_values):
    def safe_eval(expr):
        try:
            return eval(expr, {'__builtins__': None}, field_values)
        except:
            raise ValueError(f"Invalid formula: {expr}")

    return safe_eval(formula)

def parse_xml(xml_string):
    root = ET.fromstring(xml_string)
    fields = []
    for field in root.findall('field'):
        name = field.get('name')
        formula = field.get('formula')
        fields.append((name, formula))
    return fields

