    html = ['<table>']
    html.append('<tr><th>field</th><th>value</th></tr>')
    field_values = {}
    for name, formula in fields:
        value = evaluate_formula(formula, field_values)
        field_values[name] = value
        html.append(f'<tr><td>{name}</td><td>{str(value)}</td></tr>')
    html.append('</table>')
    return '\n'.join(html)

def main():
    if len(sys.argv) != 2:
        print("Usage: python formula_report.py report.xml", file=sys.stderr)
        sys.exit(1)

    with open(sys.argv[1], 'r') as f:
